SCHEMA_VERSION=1
SCHEMA_SQL="CREATE TABLE IF NOT EXISTS schema_version (version INTEGER NOT NULL, applied_at_ns INTEGER NOT NULL);\nCREATE TABLE IF NOT EXISTS embeddings (\n memory_id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, evidence_id TEXT NOT NULL, source_hash TEXT NOT NULL, provenance TEXT NOT NULL, source_revision TEXT NOT NULL, access_scope TEXT NOT NULL, source_timestamp TEXT NOT NULL, ingestion_timestamp_ns INTEGER NOT NULL, collection_id TEXT NOT NULL, chunk_id TEXT NOT NULL, chunk_start INTEGER NOT NULL, chunk_end INTEGER, model_identity TEXT NOT NULL, encoder_revision TEXT NOT NULL, artifact_sha256 TEXT NOT NULL, tokenizer_identity TEXT NOT NULL, preprocessing_identity TEXT NOT NULL, dimension INTEGER NOT NULL, dtype TEXT NOT NULL, quantization_method TEXT NOT NULL, quantization_scale REAL, vector_bytes BLOB NOT NULL, vector_checksum TEXT NOT NULL, validity_status TEXT NOT NULL CHECK(validity_status IN ('valid','invalid','superseded','corrupt')), invalid_reason TEXT\n);\nCREATE INDEX IF NOT EXISTS idx_embeddings_collection ON embeddings(collection_id,validity_status,memory_id);\nCREATE INDEX IF NOT EXISTS idx_embeddings_scope ON embeddings(access_scope,validity_status,memory_id);\nCREATE INDEX IF NOT EXISTS idx_embeddings_source ON embeddings(evidence_id,source_revision);"
